components/common/channel-selector-mobil:
{{#if theme_settings.channels.length '>' 1}}
<a href="#"
   class="navPages-action has-subMenu"
   data-collapsible="navPages-channel"
   aria-controls="navPages-channel"
   aria-expanded="false"
   aria-label="
    {{#each theme_settings.channels}}
        {{#if is_active}}
            {{lang 'common.channel' code=code}}
        {{/if}}
    {{/each}}
   "
>
    {{#each theme_settings.channels}}
        {{#if is_active}}
            {{lang 'common.channel' code=code}}
        {{/if}}
    {{/each}}
    <i class="icon navPages-action-moreIcon" aria-hidden="true">
        <svg>
            <use href="#icon-chevron-down"></use>
        </svg>
    </i>
</a>
<div class="navPage-subMenu" id="navPages-channel" aria-hidden="true" tabindex="-1">
    <ul class="navPage-subMenu-list">
        {{#each theme_settings.channels}}
        <li class="navPage-subMenu-item">
            <a href="{{{switch_url}}}"
               class="navPage-subMenu-action navPages-action"
               aria-label="{{name}}"
               data-channel-code="{{{code}}}"
               data-warning="{{lang 'common.channel_switch_warning'}}"
            >
                {{name}}
            </a>
        </li>
        {{/each}}
    </ul>
</div>
{{/if}}

components/common/currency-selector:
{{#if currency_selector.currencies.length '>' 1}}
<ul class="navUser-section">
    <li class="navUser-item">
        <div class="navUser-action navUser-action--currencySelector has-dropdown"
           data-dropdown="currencySelection"
        >
            {{lang 'common.currency' code=currency_selector.active_currency_code}}
            <i class="icon" aria-hidden="true">
                <svg>
                    <use href="#icon-chevron-down" />
                </svg>
            </i>
        </div>
        <ul class="dropdown-menu" id="currencySelection" data-dropdown-content aria-hidden="true" tabindex="-1">
            {{#each currency_selector.currencies}}
            <li class="dropdown-menu-item">
                <a href="{{{switch_url}}}"
                   data-currency-code="{{{code}}}"
                   {{#if cart_currency_switch_url.length '>' 0 }}
                   data-cart-currency-switch-url="{{{cart_currency_switch_url}}}"
                   {{/if}}
                   data-warning="{{lang 'common.currency_switch_promotion'}}"
                >
                {{#if is_active}}
                    <strong>{{name}}</strong>
                {{else}}
                    {{name}}
                {{/if}}
                </a>
            </li>
            {{/each}}
        </ul>
    </li>
</ul>
{{/if}}

components/products/bulk-discount-rates:
{{#if bulk_discount_rates.length}}
    {{#if product}}<dt class="productView-info-name">{{lang 'products.bulk_pricing.title'}}</dt>{{/if}}
    <dd class="productView-info-value">
        <a href="{{product.url}}#bulk_pricing"
           {{#unless is_ajax }}data-reveal-id="modal-bulk-pricing{{#if id}}-{{id}}{{/if}}"{{/unless}}>
            {{lang 'products.bulk_pricing.view'}}
        </a>
    </dd>
    <div id="modal-bulk-pricing{{#if id}}-{{id}}{{/if}}" class="modal modal--small" data-reveal>
        <div class="modal-header">
            <h2 class="modal-header-title">{{lang 'products.bulk_pricing.modal_title'}}</h2>
            {{> components/common/modal/modal-close-btn}}
        </div>
        <div class="modal-body">
            <p>{{lang 'products.bulk_pricing.instructions'}}</p>
            <ul>
                {{#each bulk_discount_rates}}
                <li>
                    {{lang 'products.bulk_pricing.range' min=min max=max}}
                    {{#if type '===' 'percent'}}
                    {{lang 'products.bulk_pricing.percent' discount=discount.formatted}}
                    {{else if type '===' 'fixed'}}
                    {{lang 'products.bulk_pricing.fixed' discount=discount.formatted}}
                    {{else if type '===' 'price'}}
                    {{lang 'products.bulk_pricing.price' discount=discount.formatted}}
                    {{/if}}
                </li>
                {{/each}}
            </ul>
        </div>
    </div>
{{/if}}

